1	// The fake site's truth (TESTING.md L0.M): trucks on the loop, the duty cycle, supervisory
2	// commands with their delay and queuing, leases and the deadman, e-stops, faults and blasts.
3	//
4	// It knows no site. Geometry comes from SiteConfig through src/site.ts, and the places where trucks
5	// load, dump and charge come from segment kinds ('load', 'dump', 'bay'), as PROTOCOL.md §3 names
6	// them. It never reads the wall clock: one tick timer on the injected Clock drives everything, so
7	// a ManualClock runs a day in milliseconds and the same seed and inputs replay byte for byte.
8	//
9	// What is sent is built from this truth. Milestone 2's fault injectors sit between the two
10	// (telemetry faults) and between the gateway and each client (radio faults); the truth stays here.
11	import type { Clock, TimerHandle } from '../src/clock.ts';
12	import type {
13	  Action, CommandAck, GatewayMessage, Hello, LeaseEvent, RejectReason, RouteSegment, Task, Telemetry,
14	  VehicleState, ZoneState,
15	} from '../src/protocol.ts';
16	import { buildSite, type Segment, type Site, type Zone } from '../src/site.ts';
17	import type { Behaviour } from './behaviour.ts';
18	import { Rng } from './rng.ts';
19	
20	export interface SiteConfig {
21	  site_id: string;
22	  vehicles: string[];
23	  route: RouteSegment[];
24	  loop_length_m: number;
25	  noticeMs: number; // CLOSING to effective_at for every blast at this site
26	}
27	
28	export interface TruckInit {
29	  vehicle_id: string;
30	  positionM: number;
31	  loaded?: boolean;
32	  socPct?: number;
33	  state?: 'TRAMMING' | 'HOLDING' | 'IDLE';
34	  drainFactor?: number; // a weak pack drains this many times faster (5x measured live)
35	}
36	
37	// A blast at a fixed time, relative to the model's start.
38	export interface BlastSpec {
39	  zoneId: string;
40	  atMs: number;
41	  closedForMs: number;
42	  cancelAfterMs?: number; // CANCELLED this long after CLOSING, instead of closing
43	  noticeMs?: number;      // defaults to the site's
44	}
45	
46	export type Blasts = 'random' | 'none' | BlastSpec[];
47	
48	export interface ModelOptions {
49	  seed: number;
50	  site: SiteConfig;
51	  behaviour: Behaviour;
52	  blasts: Blasts;
53	  trucks: TruckInit[];
54	}
55	
56	export type AckResult = Pick<CommandAck, 'status' | 'reason' | 'holder' | 'lease_id' | 'lease_idle_timeout_ms' | 'deadman_ms'>;
57	
58	export interface ModelCommand {
59	  command_id: string;
60	  vehicle_id: string;
61	  action: Action;
62	  operator_id: string;
63	  force?: unknown;
64	  lease_id?: unknown;
65	}
66	
67	type Supervisory = 'HOLD' | 'RESUME' | 'RETURN_TO_BAY' | 'EXIT_ZONE';
68	
69	// What is true, for tests: never sent, always a copy.
70	export interface TruckTruth {
71	  vehicleId: string;
72	  positionM: number;
73	  segmentId: string;
74	  zoneId: string;
75	  offsetM: number;
76	  state: VehicleState;
77	  task: Task | null;
78	  mode: 'AUTO' | 'MANUAL';
79	  speedMps: number;
80	  direction: 'FWD' | 'REV';
81	  socPct: number;
82	  loaded: boolean;
83	  faults: string[];
84	  leaseId: string | null;
85	  operatorId: string | null;
86	  deadman: boolean;
87	  throttle: number;
88	  queued: Supervisory | null;   // waiting behind LOADING / DUMPING / CHARGING
89	  pending: Supervisory[];       // accepted, not yet in effect (the 1-6 s delay)
90	  drainFactor: number;
91	}
92	
93	interface Effect { action: Supervisory; zoneId: string | null; due: number }
94	interface Work { kind: 'LOADING' | 'DUMPING' | 'CHARGING'; until: number | null; then: 'TRAMMING' | 'IDLE' }
95	interface Move { dir: 1 | -1; remaining: number; target: number }
96	interface Lease { id: string; operator: string; lastFresh: number }
97	
98	interface Truck {
99	  id: string;
100	  pos: number;
101	  speed: number;
102	  dir: 1 | -1;
103	  state: VehicleState;
104	  task: Task | null;
105	  soc: number;
106	  loaded: boolean;
107	  faults: string[];
108	  drainFactor: number;
109	  work: Work | null;
110	  move: Move | null;
111	  queued: Effect | null;
112	  pending: Effect[];
113	  lease: Lease | null;
114	  throttle: number;
115	  deadman: boolean;
116	  lastDriveSeq: number | null;
117	  lastDriveSentMs: number | null;
118	  seq: number;
119	  phase: number;
120	  deviceOffsetMs: number; // the vehicle clock's error; 0 until milestone 2's skew injector
121	}
122	
123	interface Blast {
124	  zoneId: string;
125	  closingAt: number;
126	  effectiveAt: number;
127	  reopenAt: number;
128	  cancelAt: number | null;
129	  stage: 'scheduled' | 'closing' | 'closed' | 'done';
130	}
131	
132	const EPS = 1e-9;
133	const WORK_STATES: readonly VehicleState[] = ['LOADING', 'DUMPING', 'CHARGING'];
134	const isWork = (s: VehicleState) => WORK_STATES.includes(s);
135	const round2 = (x: number) => Math.round(x * 100) / 100;
136	
137	export class SiteModel {
138	  readonly site: Site;
139	  readonly startMs: number;
140	  readonly #clock: Clock;
141	  readonly #emit: (m: GatewayMessage) => void;
142	  readonly #b: Behaviour;
143	  readonly #config: SiteConfig;
144	  readonly #trucks: Truck[];
145	  readonly #byId: Map<string, Truck>;
146	  readonly #zones: Map<string, ZoneState>;
147	  readonly #segments: readonly Segment[];
148	  readonly #points: { LOADING: number[]; DUMPING: number[]; CHARGING: number[] };
149	  readonly #rngCommands: Rng;
150	  readonly #rngBlasts: Rng;
151	  readonly #rngLeases: Rng;
152	  readonly #randomBlasts: boolean;
153	  readonly #telemetryEvery: number;
154	  #blasts: Blast[] = [];
155	  #nextRandomBlastAt = Infinity;
156	  #leaseCount = 0;
157	  #driveRejectedAt = new Map<string, number>();
158	  #timer: TimerHandle | null = null;
159	  #lastTick: number;
160	  #ticks = 0;
161	  #nextHeartbeat: number;
162	
163	  constructor(clock: Clock, emit: (m: GatewayMessage) => void, opts: ModelOptions) {
164	    this.#clock = clock;
165	    this.#emit = emit;
166	    this.#b = opts.behaviour;
167	    this.#config = opts.site;
168	    this.startMs = clock.now();
169	    this.#lastTick = this.startMs;
170	    this.#nextHeartbeat = this.startMs + this.#b.heartbeatPeriodMs;
171	    this.#telemetryEvery = Math.max(1, Math.round(this.#b.telemetryPeriodMs / this.#b.tickMs));
172	
173	    const { site, issues } = buildSite({ ...this.#helloShape(), zones: [], leases: [] });
174	    if (issues.length > 0) throw new Error(`site config does not add up: ${issues.join('; ')}`);
175	    this.site = site;
176	    this.#segments = site.segments;
177	    const pointsOf = (kind: string) =>
178	      this.#segments.filter((s) => s.kind === kind).map((s) => s.startM + s.lengthM - this.#b.workStopBeforeEndM);
179	    this.#points = { LOADING: pointsOf('load'), DUMPING: pointsOf('dump'), CHARGING: pointsOf('bay') };
180	    this.#zones = new Map(site.zones.map((z) => [z.zoneId, { zone_id: z.zoneId, status: 'OPEN', effective_at_ms: null, reason: null }]));
181	
182	    const root = new Rng(opts.seed);
183	    const rngInit = root.fork('init');
184	    this.#rngCommands = root.fork('commands');
185	    this.#rngBlasts = root.fork('blasts');
186	    this.#rngLeases = root.fork('leases');
187	
188	    const given = new Map(opts.trucks.map((t) => [t.vehicle_id, t]));
189	    for (const id of given.keys()) if (!site.vehicles.includes(id)) throw new Error(`truck ${id} is not on the site's roster`);
190	    const n = site.vehicles.length;
191	    this.#trucks = site.vehicles.map((id, i) => {
192	      // Default placement: spread round the loop with jitter, loaded between the load and dump points.
193	      const jitter = rngInit.uniform(-0.2, 0.2);
194	      const socDefault = rngInit.uniform(35, 95);
195	      const init = given.get(id);
196	      const pos = this.#mod(init ? init.positionM : (i + 0.5 + jitter) * (site.loopLengthM / n));
197	      return {
198	        id, pos, speed: 0, dir: 1, state: init?.state ?? 'TRAMMING', task: null,
199	        soc: init?.socPct ?? socDefault, loaded: init?.loaded ?? this.#loadedAt(pos), faults: [],
200	        drainFactor: init?.drainFactor ?? 1, work: null, move: null, queued: null, pending: [],
201	        lease: null, throttle: 0, deadman: false, lastDriveSeq: null, lastDriveSentMs: null,
202	        seq: 0, phase: i % this.#telemetryEvery, deviceOffsetMs: 0,
203	      } satisfies Truck;
204	    });
205	    this.#byId = new Map(this.#trucks.map((t) => [t.id, t]));
206	
207	    this.#randomBlasts = opts.blasts === 'random';
208	    if (opts.blasts === 'random') {
209	      this.#nextRandomBlastAt = this.startMs + this.#onTick(this.#rngBlasts.uniform(this.#b.firstBlastMinMs, this.#b.firstBlastMaxMs));
210	    } else if (Array.isArray(opts.blasts)) {
211	      for (const s of opts.blasts) {
212	        if (!this.#zones.has(s.zoneId)) throw new Error(`blast zone ${s.zoneId} is not on the site`);
213	        const closingAt = this.startMs + s.atMs;
214	        const effectiveAt = closingAt + (s.noticeMs ?? this.#config.noticeMs);
215	        this.#blasts.push({
216	          zoneId: s.zoneId, closingAt, effectiveAt, reopenAt: effectiveAt + s.closedForMs,
217	          cancelAt: s.cancelAfterMs === undefined ? null : closingAt + s.cancelAfterMs, stage: 'scheduled',
218	        });
219	      }
220	    }
221	  }
222	
223	  // ---- lifecycle ----
224	
225	  start(): void {
226	    if (this.#timer) return;
227	    this.#timer = this.#clock.setTimeout(this.#tick, this.#b.tickMs);
228	  }
229	
230	  stop(): void {
231	    if (this.#timer) this.#clock.clearTimeout(this.#timer);
232	    this.#timer = null;
233	  }
234	
235	  // ---- what a client sees on connecting ----
236	
237	  hello(email: string): Hello {
238	    return {
239	      ...this.#helloShape(),
240	      zones: [...this.#zones.values()].map((z) => ({ ...z })),
241	      leases: this.#trucks.filter((t) => t.lease).map((t) => ({ vehicle_id: t.id, operator_id: t.lease!.operator })),
242	      site: { name: email },
243	    };
244	  }
245	
246	  #helloShape(): Omit<Hello, 'zones' | 'leases' | 'site'> {
247	    const c = this.#config;
248	    return {
249	      type: 'hello', protocol: '3.0', site_id: c.site_id, server_time_ms: this.#clock.now(), vehicles: [...c.vehicles],
250	      route: c.route.map((r) => ({ ...r })), loop_length_m: c.loop_length_m,
251	    };
252	  }
253	
254	  // ---- truth, for tests ----
255	
256	  hasVehicle(id: string): boolean {
257	    return this.#byId.has(id);
258	  }
259	
260	  truth(id: string): TruckTruth {
261	    const t = this.#byId.get(id);
262	    if (!t) throw new Error(`no truck ${id}`);
263	    const { seg, offset } = this.#locate(t.pos);
264	    return {
265	      vehicleId: t.id, positionM: t.pos, segmentId: seg.segmentId, zoneId: seg.zoneId, offsetM: offset,
266	      state: t.state, task: t.task, mode: t.lease ? 'MANUAL' : 'AUTO', speedMps: t.speed, direction: this.#direction(t),
267	      socPct: t.soc, loaded: t.loaded, faults: [...t.faults], leaseId: t.lease?.id ?? null,
268	      operatorId: t.lease?.operator ?? null, deadman: t.deadman, throttle: t.throttle,
269	      queued: t.queued?.action ?? null, pending: t.pending.map((e) => e.action), drainFactor: t.drainFactor,
270	    };
271	  }
272	
273	  truthAll(): TruckTruth[] {
274	    return this.#trucks.map((t) => this.truth(t.id));
275	  }
276	
277	  zone(id: string): ZoneState {
278	    const z = this.#zones.get(id);
279	    if (!z) throw new Error(`no zone ${id}`);
280	    return { ...z };
281	  }
282	
283	  // ---- faults (the model's side; which truck and when is milestone 2's injector) ----
284	
285	  injectFault(id: string, code: string): void {
286	    const t = this.#byId.get(id);
287	    if (!t) throw new Error(`no truck ${id}`);
288	    this.#fault(t, code, this.#clock.now());
289	  }
290	
291	  #fault(t: Truck, code: string, now: number): void {
292	    if (!t.faults.includes(code)) t.faults.push(code);
293	    if (t.state === 'ESTOPPED') return;
294	    if (t.lease) {
295	      if (this.#limpOk(t)) return; // §6.6: keeps driving, reports MANUAL with its faults
296	      this.#emitLease(t, 'REVOKED', t.lease, now, { reason: 'FAULT' });
297	      this.#endLease(t);
298	    }
299	    this.#stopAll(t);
300	    t.state = 'FAULT';
301	  }
302	
303	  #limpOk(t: Truck): boolean {
304	    return t.faults.every((f) => this.#b.limpHomeFaults.includes(f));
305	  }
306	
307	  // ---- commands (already validated by the gateway: id, operator, vehicle, action) ----
308	
309	  command(c: ModelCommand): AckResult {
310	    const t = this.#byId.get(c.vehicle_id);
311	    if (!t) return reject('UNKNOWN_VEHICLE');
312	    const now = this.#clock.now();
313	
314	    if (c.action === 'ESTOP') {
315	      this.#estop(t, c.operator_id, now);
316	      return ACCEPTED;
317	    }
318	    if (t.state === 'ESTOPPED') {
319	      if (c.action !== 'CLEAR_ESTOP') return reject('ESTOP_ACTIVE');
320	      t.state = t.faults.length > 0 ? 'FAULT' : 'HOLDING';
321	      return ACCEPTED;
322	    }
323	    if (t.faults.length > 0 && !(this.#limpOk(t) && (c.action === 'TAKE_CONTROL' || c.action === 'RELEASE_CONTROL'))) {
324	      return reject('INTERLOCK_ACTIVE');
325	    }
326	    switch (c.action) {
327	      case 'CLEAR_ESTOP': return reject('INVALID_STATE');
328	      case 'TAKE_CONTROL': return this.#takeControl(t, c.operator_id, c.force === true, now);
329	      case 'RELEASE_CONTROL': return this.#release(t, c.lease_id, now);
330	      default: break;
331	    }
332	    if (t.lease) return reject('LEASE_HELD', { holder: t.lease.operator });
333	    return this.#supervisory(t, c.action, now);
334	  }
335	
336	  #supervisory(t: Truck, action: Supervisory, now: number): AckResult {
337	    if (action === 'RESUME') {
338	      // §5: RESUME cancels a queued command instead, at once (the controller has it in its queue).
339	      if (t.queued) { t.queued = null; return ACCEPTED; }
340	      if (t.state === 'HOLDING' || t.state === 'IDLE') { this.#schedule(t, { action, zoneId: null }, now); return ACCEPTED; }
341	      return reject('INVALID_STATE');
342	    }
343	    let zoneId: string | null = null;
344	    if (action === 'EXIT_ZONE') {
345	      const z = this.site.zoneAt(t.pos);
346	      if (!z || z.kinds.includes('bay')) return reject('INVALID_STATE');
347	      zoneId = z.zoneId; // §5: the zone it was in when the command was accepted
348	    }
349	    if (action === 'RETURN_TO_BAY' && this.#points.CHARGING.length === 0) return reject('INVALID_STATE');
350	    if (isWork(t.state)) {
351	      t.queued = { action, zoneId, due: now }; // one at a time: a newer one replaces the older
352	      return ACCEPTED;
353	    }
354	    this.#schedule(t, { action, zoneId }, now);
355	    return ACCEPTED;
356	  }
357	
358	  // Supervisory commands take effect 1-6 s after acceptance, in the order they were accepted.
359	  #schedule(t: Truck, e: Omit<Effect, 'due'>, now: number): void {
360	    const delay = Math.round(this.#rngCommands.uniform(this.#b.commandDelayMinMs, this.#b.commandDelayMaxMs));
361	    const due = Math.max(now + delay, t.pending.at(-1)?.due ?? 0);
362	    t.pending.push({ ...e, due });
363	  }
364	
365	  #apply(t: Truck, e: Effect, now: number): void {
366	    if (t.state === 'MANUAL' || t.state === 'ESTOPPED' || t.state === 'FAULT') return;
367	    if (isWork(t.state)) {
368	      if (e.action !== 'RESUME') t.queued = e;
369	      return;
370	    }
371	    switch (e.action) {
372	      case 'HOLD':
373	        this.#hold(t);
374	        return;
375	      case 'RESUME':
376	        if (t.state === 'HOLDING' || t.state === 'IDLE') { t.state = 'TRAMMING'; t.task = null; t.move = null; }
377	        return;
378	      case 'EXIT_ZONE': {
379	        const z = this.site.zoneAt(t.pos);
380	        if (!z || z.zoneId !== e.zoneId) { this.#hold(t); return; } // already left: just hold
381	        t.state = 'TRAMMING';
382	        t.task = 'EXIT_ZONE';
383	        t.move = this.#exitMove(t.pos, z);
384	        return;
385	      }
386	      case 'RETURN_TO_BAY':
387	        t.state = 'TRAMMING';
388	        t.task = 'RETURN_TO_BAY';
389	        t.move = this.#bayMove(t.pos);
390	        if (t.move.remaining <= EPS) this.#arrive(t);
391	        return;
392	    }
393	  }
394	
395	  #hold(t: Truck): void {
396	    t.state = 'HOLDING';
397	    t.task = null;
398	    t.move = null;
399	    t.speed = 0;
400	    t.dir = 1;
401	  }
402	
403	  // Nearest boundary of the zone, forward or reverse, to stop a little outside it.
404	  #exitMove(pos: number, z: Zone): Move {
405	    const stop = this.#b.exitStopOutsideM;
406	    for (const r of z.ranges) {
407	      const back = this.#mod(pos - r.startM);
408	      if (back >= r.lengthM) continue;
409	      const fwd = r.lengthM - back;
410	      return fwd <= back
411	        ? { dir: 1, remaining: fwd + stop, target: this.#mod(pos + fwd + stop) }
412	        : { dir: -1, remaining: back + stop, target: this.#mod(pos - back - stop) };
413	    }
414	    return { dir: 1, remaining: 0, target: pos };
415	  }
416	
417	  // To the charging point at the end of the nearest bay segment, by the shorter direction.
418	  #bayMove(pos: number): Move {
419	    let best: Move | null = null;
420	    for (const p of this.#points.CHARGING) {
421	      const fwd = this.#mod(p - pos), rev = this.#mod(pos - p);
422	      const m: Move = rev < fwd ? { dir: -1, remaining: rev, target: p } : { dir: 1, remaining: fwd, target: p };
423	      if (!best || m.remaining < best.remaining) best = m;
424	    }
425	    return best!;
426	  }
427	
428	  // ---- leases (§6) ----
429	
430	  #takeControl(t: Truck, operator: string, force: boolean, now: number): AckResult {
431	    if (t.lease) {
432	      if (t.lease.operator === operator) return this.#leaseAck(t.lease); // §6.5: the existing lease
433	      if (!force) return reject('LEASE_HELD', { holder: t.lease.operator });
434	      this.#emitLease(t, 'REVOKED', t.lease, now, { reason: 'FORCED_TAKEOVER', by_operator: operator });
435	      t.lease = null;
436	    }
437	    const lease: Lease = { id: `L-${String(++this.#leaseCount).padStart(5, '0')}-${this.#rngLeases.hex(4)}`, operator, lastFresh: now };
438	    this.#stopAll(t); // interrupts loading, dumping or charging, and drops queued and pending commands
439	    t.lease = lease;
440	    t.state = 'MANUAL';
441	    t.throttle = 0;
442	    t.deadman = false;
443	    t.lastDriveSeq = 0; // as seen live: 0 after the grant, before any drive message
444	    t.lastDriveSentMs = null;
445	    this.#emitLease(t, 'GRANTED', lease, now, { forced: force });
446	    return this.#leaseAck(lease);
447	  }
448	
449	  #leaseAck(lease: Lease): AckResult {
450	    return { status: 'ACCEPTED', lease_id: lease.id, lease_idle_timeout_ms: this.#b.leaseIdleTimeoutMs, deadman_ms: this.#b.deadmanMs };
451	  }
452	
453	  #release(t: Truck, leaseId: unknown, now: number): AckResult {
454	    if (!t.lease || leaseId !== t.lease.id) return reject('NOT_LEASE_HOLDER');
455	    this.#emitLease(t, 'RELEASED', t.lease, now, {});
456	    this.#endLease(t);
457	    return ACCEPTED;
458	  }
459	
460	  #endLease(t: Truck): void {
461	    t.lease = null;
462	    t.throttle = 0;
463	    t.deadman = false;
464	    t.lastDriveSeq = null;
465	    t.lastDriveSentMs = null;
466	    t.speed = 0;
467	    t.dir = 1;
468	    t.state = t.faults.length > 0 ? 'FAULT' : 'HOLDING'; // §6.4, §6.6: holds, or back to FAULT
469	  }
470	
471	  #estop(t: Truck, operator: string, now: number): void {
472	    if (t.lease) {
473	      this.#emitLease(t, 'REVOKED', t.lease, now, { reason: 'ESTOP', by_operator: operator });
474	      this.#endLease(t);
475	    }
476	    this.#stopAll(t);
477	    t.state = 'ESTOPPED';
478	  }
479	
480	  #emitLease(t: Truck, event: LeaseEvent['event'], lease: Lease, now: number, extra: Partial<LeaseEvent>): void {
481	    this.#emit({
482	      type: 'lease_event', vehicle_id: t.id, event, lease_id: lease.id, operator_id: lease.operator,
483	      ...(extra.reason !== undefined ? { reason: extra.reason } : {}),
484	      ...(extra.by_operator !== undefined ? { by_operator: extra.by_operator } : {}),
485	      server_time_ms: now,
486	      ...(extra.forced !== undefined ? { forced: extra.forced } : {}),
487	    });
488	  }
489	
490	  drive(msg: Record<string, unknown>): void {
491	    const now = this.#clock.now();
492	    const vehicle = typeof msg.vehicle_id === 'string' ? msg.vehicle_id : String(msg.vehicle_id);
493	    const leaseId = typeof msg.lease_id === 'string' ? msg.lease_id : null;
494	    const t = this.#byId.get(vehicle);
495	    if (!t) return this.#driveRejected(vehicle, leaseId, 'UNKNOWN_VEHICLE', now);
496	    if (!t.lease || leaseId !== t.lease.id) return this.#driveRejected(vehicle, leaseId, 'NO_ACTIVE_LEASE', now);
497	    const throttle = msg.throttle;
498	    if (typeof throttle !== 'number' || !Number.isFinite(throttle) || throttle < -1 || throttle > 1) {
499	      return this.#driveRejected(vehicle, leaseId, 'BAD_THROTTLE', now);
500	    }
501	    const seq = msg.seq;
502	    if (typeof seq !== 'number' || !Number.isInteger(seq) || seq < 1) return this.#driveRejected(vehicle, leaseId, 'BAD_SEQ', now);
503	    if (seq <= (t.lastDriveSeq ?? 0)) return; // §6.2: not higher than the last applied: discarded
504	    t.throttle = throttle;
505	    t.lastDriveSeq = seq;
506	    t.lastDriveSentMs = typeof msg.sent_ms === 'number' ? msg.sent_ms : null;
507	    t.lease.lastFresh = now;
508	    t.deadman = false;
509	  }
510	
511	  #driveRejected(vehicle: string, leaseId: string | null, reason: 'NO_ACTIVE_LEASE' | 'BAD_THROTTLE' | 'BAD_SEQ' | 'UNKNOWN_VEHICLE', now: number): void {
512	    const key = `${vehicle}\u0000${reason}`;
513	    const last = this.#driveRejectedAt.get(key);
514	    if (last !== undefined && now - last < this.#b.driveRejectIntervalMs) return;
515	    this.#driveRejectedAt.set(key, now);
516	    this.#emit({ type: 'drive_rejected', vehicle_id: vehicle, lease_id: leaseId as string, reason, server_time_ms: now });
517	  }
518	
519	  // ---- the tick ----
520	
521	  #tick = (): void => {
522	    const now = this.#clock.now();
523	    const dt = (now - this.#lastTick) / 1000;
524	    this.#lastTick = now;
525	    this.#runBlasts(now);
526	    for (const t of this.#trucks) {
527	      this.#leaseTimers(t, now);
528	      while (t.pending.length > 0 && t.pending[0]!.due <= now) this.#apply(t, t.pending.shift()!, now);
529	      this.#advance(t, dt, now);
530	    }
531	    this.#ticks++;
532	    for (const t of this.#trucks) {
533	      if ((this.#ticks + t.phase) % this.#telemetryEvery === 0) this.#emit(this.#telemetry(t, now));
534	    }
535	    if (now >= this.#nextHeartbeat) {
536	      this.#emit({ type: 'heartbeat', server_time_ms: now });
537	      this.#nextHeartbeat += this.#b.heartbeatPeriodMs;
538	    }
539	    this.#timer = this.#clock.setTimeout(this.#tick, this.#b.tickMs);
540	  };
541	
542	  #leaseTimers(t: Truck, now: number): void {
543	    if (!t.lease) return;
544	    const idle = now - t.lease.lastFresh;
545	    if (idle >= this.#b.leaseIdleTimeoutMs) {
546	      this.#emitLease(t, 'EXPIRED', t.lease, now, { reason: 'NO_DRIVE_INPUT' });
547	      this.#endLease(t);
548	    } else if (idle >= this.#b.deadmanMs) {
549	      t.deadman = true;
550	    }
551	  }
552	
553	  #advance(t: Truck, dt: number, now: number): void {
554	    switch (t.state) {
555	      case 'LOADING':
556	      case 'DUMPING':
557	        t.speed = 0;
558	        if (t.work!.until !== null && now >= t.work!.until) this.#finishWork(t, now);
559	        return;
560	      case 'CHARGING':
561	        t.speed = 0;
562	        t.soc = Math.min(this.#b.chargeToPct, t.soc + this.#b.chargeRatePctPerS * dt);
563	        if (t.soc >= this.#b.chargeToPct) this.#finishWork(t, now);
564	        return;
565	      case 'TRAMMING':
566	        if (t.move) this.#moveTask(t, dt, now);
567	        else this.#moveDuty(t, dt, now);
568	        return;
569	      case 'MANUAL':
570	        this.#moveManual(t, dt, now);
571	        return;
572	      default:
573	        t.speed = 0;
574	    }
575	  }
576	
577	  // The autonomous duty cycle: forward, stopping to load, dump or charge where the route says.
578	  #moveDuty(t: Truck, dt: number, now: number): void {
579	    t.speed = t.loaded ? this.#b.autoSpeedLoaded : this.#b.autoSpeedEmpty;
580	    t.dir = 1;
581	    const d = t.speed * dt;
582	    const kinds: Array<Work['kind']> = [t.loaded ? 'DUMPING' : 'LOADING'];
583	    if (t.soc < this.#b.chargeBelowPct) kinds.push('CHARGING');
584	    let s: { dist: number; point: number; kind: Work['kind'] } | null = null;
585	    for (const kind of kinds) {
586	      for (const p of this.#points[kind]) {
587	        const dist = this.#mod(p - t.pos);
588	        if (dist > EPS && dist <= d + EPS && (!s || dist < s.dist)) s = { dist, point: p, kind };
589	      }
590	    }
591	    if (!s) { this.#travel(t, d, now); return; }
592	    if (!this.#travel(t, s.dist, now)) return;
593	    t.pos = s.point;
594	    t.speed = 0;
595	    t.state = s.kind;
596	    const until = s.kind === 'LOADING' ? now + this.#b.loadMs : s.kind === 'DUMPING' ? now + this.#b.dumpMs : null;
597	    t.work = { kind: s.kind, until, then: 'TRAMMING' };
598	  }
599	
600	  // EXIT_ZONE and RETURN_TO_BAY: to a target, forward or reverse, ignoring the duty cycle.
601	  #moveTask(t: Truck, dt: number, now: number): void {
602	    const m = t.move!;
603	    t.dir = m.dir;
604	    t.speed = m.dir > 0
605	      ? (t.loaded ? this.#b.autoSpeedLoaded : this.#b.autoSpeedEmpty)
606	      : (t.loaded ? this.#b.reverseSpeedLoaded : this.#b.reverseSpeedEmpty);
607	    const d = Math.min(t.speed * dt, m.remaining);
608	    if (!this.#travel(t, d * m.dir, now)) return;
609	    m.remaining -= d;
610	    if (m.remaining <= EPS) {
611	      t.pos = m.target;
612	      this.#arrive(t);
613	    }
614	  }
615	
616	  #arrive(t: Truck): void {
617	    t.move = null;
618	    t.speed = 0;
619	    t.dir = 1;
620	    if (t.task === 'EXIT_ZONE') { t.state = 'HOLDING'; t.task = null; return; }
621	    if (t.soc < this.#b.chargeToPct) {
622	      t.state = 'CHARGING';
623	      t.work = { kind: 'CHARGING', until: null, then: 'IDLE' }; // task stays RETURN_TO_BAY until parked
624	    } else {
625	      t.state = 'IDLE';
626	      t.task = null;
627	    }
628	  }
629	
630	  #finishWork(t: Truck, now: number): void {
631	    const w = t.work!;
632	    t.work = null;
633	    if (w.kind === 'LOADING') t.loaded = true;
634	    if (w.kind === 'DUMPING') t.loaded = false;
635	    if (w.then === 'IDLE') { t.state = 'IDLE'; t.task = null; } else t.state = 'TRAMMING';
636	    if (t.queued) {
637	      const q = t.queued;
638	      t.queued = null;
639	      this.#apply(t, q, now);
640	    }
641	  }
642	
643	  // Moves only on fresh input: the deadman (set in #leaseTimers) stops it, and nothing re-applies
644	  // an old throttle once it has tripped.
645	  #moveManual(t: Truck, dt: number, now: number): void {
646	    if (t.deadman || t.throttle === 0) { t.speed = 0; return; }
647	    const max = t.faults.length > 0 ? this.#b.limpSpeed : t.loaded ? this.#b.manualSpeedLoaded : this.#b.manualSpeedEmpty;
648	    t.speed = Math.abs(t.throttle) * max;
649	    t.dir = t.throttle > 0 ? 1 : -1;
650	    this.#travel(t, t.speed * dt * t.dir, now);
651	  }
652	
653	  // Moves along the loop, paying for it in charge. Returns false if the pack ran out on the way,
654	  // in which case the truck stops exactly where it did.
655	  #travel(t: Truck, signedM: number, now: number): boolean {
656	    const dist = Math.abs(signedM);
657	    if (dist === 0) return true;
658	    const perM = ((t.loaded ? this.#b.drainLoadedPctPerKm : this.#b.drainEmptyPctPerKm) / 1000) * t.drainFactor;
659	    const cost = dist * perM;
660	    if (cost >= t.soc) {
661	      t.pos = this.#mod(t.pos + Math.sign(signedM) * (t.soc / perM));
662	      t.soc = 0;
663	      this.#fault(t, this.#b.depletedFault, now);
664	      return false;
665	    }
666	    t.pos = this.#mod(t.pos + signedM);
667	    t.soc -= cost;
668	    return true;
669	  }
670	
671	  #stopAll(t: Truck): void {
672	    t.speed = 0;
673	    t.dir = 1;
674	    t.work = null;
675	    t.move = null;
676	    t.task = null;
677	    t.queued = null;
678	    t.pending = [];
679	  }
680	
681	  // ---- blasts ----
682	
683	  #runBlasts(now: number): void {
684	    while (this.#randomBlasts && now >= this.#nextRandomBlastAt) {
685	      this.#scheduleRandomBlast(this.#nextRandomBlastAt);
686	      this.#nextRandomBlastAt += this.#onTick(this.#rngBlasts.uniform(this.#b.blastSpacingMinMs, this.#b.blastSpacingMaxMs));
687	    }
688	    for (const b of this.#blasts) {
689	      if (b.stage === 'scheduled' && now >= b.closingAt) {
690	        this.#setZone(b.zoneId, 'CLOSING', b.effectiveAt, 'BLAST_WINDOW', now);
691	        b.stage = 'closing';
692	      }
693	      if (b.stage === 'closing') {
694	        if (b.cancelAt !== null && now >= b.cancelAt) {
695	          this.#setZone(b.zoneId, 'OPEN', now, 'CANCELLED', now);
696	          b.stage = 'done';
697	        } else if (now >= b.effectiveAt) {
698	          this.#setZone(b.zoneId, 'CLOSED', now, 'BLAST_WINDOW', now);
699	          b.stage = 'closed';
700	        }
701	      }
702	      if (b.stage === 'closed' && now >= b.reopenAt) {
703	        this.#setZone(b.zoneId, 'OPEN', now, 'CLEARED', now);
704	        b.stage = 'done';
705	      }
706	    }
707	    this.#blasts = this.#blasts.filter((b) => b.stage !== 'done');
708	  }
709	
710	  #scheduleRandomBlast(at: number): void {
711	    const r = this.#rngBlasts;
712	    const busy = new Set(this.#blasts.map((b) => b.zoneId));
713	    const candidates = this.site.zones
714	      .filter((z) => this.#b.blastBay || !z.kinds.includes('bay'))
715	      .map((z) => z.zoneId)
716	      .filter((id) => !busy.has(id));
717	    const add = (zoneId: string, closingAt: number) => {
718	      const effectiveAt = closingAt + this.#config.noticeMs;
719	      const cancel = r.chance(this.#b.cancelProbability);
720	      const cancelAt = closingAt + this.#onTick(r.uniform(0.1, 0.9) * this.#config.noticeMs);
721	      this.#blasts.push({
722	        zoneId, closingAt, effectiveAt, reopenAt: effectiveAt + this.#onTick(r.uniform(this.#b.closedMinMs, this.#b.closedMaxMs)),
723	        cancelAt: cancel ? cancelAt : null, stage: 'scheduled',
724	      });
725	    };
726	    if (candidates.length === 0) return;
727	    const first = r.pick(candidates);
728	    add(first, at);
729	    const rest = candidates.filter((id) => id !== first);
730	    if (rest.length > 0 && r.chance(this.#b.secondZoneProbability)) add(r.pick(rest), at + this.#onTick(this.#b.secondZoneOffsetMs));
731	  }
732	
733	  #setZone(zoneId: string, status: ZoneState['status'], effectiveAt: number, reason: string, now: number): void {
734	    this.#zones.set(zoneId, { zone_id: zoneId, status, effective_at_ms: effectiveAt, reason });
735	    this.#emit({ type: 'zone_event', zone_id: zoneId, status, reason, effective_at_ms: effectiveAt, server_time_ms: now });
736	  }
737	
738	  // ---- telemetry ----
739	
740	  #telemetry(t: Truck, now: number): Telemetry {
741	    const { seg, offset } = this.#locate(t.pos);
742	    return {
743	      type: 'telemetry', vehicle_id: t.id, seq: ++t.seq, t_device_ms: now + t.deviceOffsetMs, state: t.state, task: t.task,
744	      soc_pct: round2(t.soc), speed_mps: round2(t.speed), direction: this.#direction(t), segment_id: seg.segmentId,
745	      zone_id: seg.zoneId, offset_m: offset, payload_kg: t.loaded ? this.#b.payloadKg : 0, faults: [...t.faults],
746	      control: {
747	        mode: t.lease ? 'MANUAL' : 'AUTO', operator_id: t.lease?.operator ?? null, deadman: t.deadman,
748	        last_drive_seq: t.lastDriveSeq, last_drive_sent_ms: t.lastDriveSentMs,
749	      },
750	    };
751	  }
752	
753	  #direction(t: Truck): 'FWD' | 'REV' {
754	    return t.speed > 0 && t.dir < 0 ? 'REV' : 'FWD';
755	  }
756	
757	  // ---- geometry ----
758	
759	  #mod(x: number): number {
760	    const l = this.site.loopLengthM;
761	    const m = ((x % l) + l) % l;
762	    return m >= l ? 0 : m;
763	  }
764	
765	  // The segment holding a position, and the offset into it (rounded as the live site reports it,
766	  // and never rounded up onto the next segment's start).
767	  #locate(pos: number): { seg: Segment; offset: number } {
768	    const p = this.#mod(pos);
769	    let seg = this.#segments[0]!;
770	    for (const s of this.#segments) if (s.startM <= p + EPS) seg = s;
771	    const raw = Math.max(0, p - seg.startM);
772	    let offset = round2(raw);
773	    if (offset >= seg.lengthM) offset = Math.floor((seg.lengthM - 0.005) * 100) / 100;
774	    return { seg, offset };
775	  }
776	
777	  #loadedAt(pos: number): boolean {
778	    const load = this.#points.LOADING[0], dump = this.#points.DUMPING[0];
779	    if (load === undefined || dump === undefined) return false;
780	    return this.#mod(pos - load) < this.#mod(dump - load);
781	  }
782	
783	  // Round a duration to whole ticks, so scheduled events land exactly on a tick.
784	  #onTick(ms: number): number {
785	    return Math.round(ms / this.#b.tickMs) * this.#b.tickMs;
786	  }
787	}
788	
789	const ACCEPTED: AckResult = Object.freeze({ status: 'ACCEPTED' }) as AckResult;
790	
791	function reject(reason: RejectReason, extra: { holder?: string } = {}): AckResult {
792	  return { status: 'REJECTED', reason, ...extra };
793	}
