// Shared harness for the fake gateway tests: a fake on a ManualClock with one authenticated
// in-process client. Not a test file itself (no .test.ts suffix).
import { ManualClock } from '../src/clock.ts';
import type { CommandAck, GatewayMessage, Telemetry } from '../src/protocol.ts';
import { FakeGateway, type FakeConfig, type TestClient } from '../fake/gateway.ts';
import { DLH1 } from '../fake/dlh1.ts';

export const T0 = 1_790_000_000_000;

export interface Harness {
  clock: ManualClock;
  gw: FakeGateway;
  client: TestClient;
  advance(ms: number): void;
  command(vehicle: string, action: string, extra?: Record<string, unknown>, operator?: string): CommandAck;
  sendCommand(body: Record<string, unknown>): CommandAck | undefined;
  drive(vehicle: string, leaseId: string, seq: number, throttle: number, sentMs?: number): void;
  latest(vehicle: string): Telemetry;
  telemetry(vehicle: string): Telemetry[];
  messages<T extends GatewayMessage['type']>(type: T): Array<Extract<GatewayMessage, { type: T }>>;
  // Advance in ticks until pred holds on the vehicle's telemetry; returns the elapsed ms, or -1.
  until(vehicle: string, pred: (t: Telemetry) => boolean, maxMs: number): number;
}

export function harness(config: Partial<FakeConfig> = {}, email = '<redacted-email>'): Harness {
  const clock = new ManualClock(T0);
  const gw = new FakeGateway(clock, { seed: 7, site: DLH1, blasts: 'none', ...config });
  gw.start();
  const client = gw.connect();
  let n = 0;

  // Indexed as lines arrive: re-scanning every message on every poll is quadratic.
  const byType = new Map<string, GatewayMessage[]>();
  const byVehicle = new Map<string, Telemetry[]>();
  const acks = new Map<string, CommandAck>();
  client.onMessage((m) => {
    const list = byType.get(m.type) ?? [];
    list.push(m);
    byType.set(m.type, list);
    if (m.type === 'telemetry') {
      const v = byVehicle.get(m.vehicle_id) ?? [];
      v.push(m);
      byVehicle.set(m.vehicle_id, v);
    }
    if (m.type === 'command_ack') acks.set(m.command_id, m);
  });
  const messages = <T extends GatewayMessage['type']>(type: T) => (byType.get(type) ?? []) as Array<Extract<GatewayMessage, { type: T }>>;
  const lastAck = (id: string) => acks.get(id);
  const telemetry = (v: string) => byVehicle.get(v) ?? [];
  client.send({ type: 'auth', email });

  const h: Harness = {
    clock, gw, client,
    advance: (ms) => clock.advance(ms),
    command(vehicle, action, extra = {}, operator = 'op1') {
      const command_id = `t-${++n}`;
      client.send({ type: 'command', command_id, vehicle_id: vehicle, action, operator_id: operator, ...extra });
      const ack = lastAck(command_id);
      if (!ack) throw new Error(`no ack for ${command_id}`);
      return ack;
    },
    sendCommand(body) {
      client.send({ type: 'command', ...body });
      return typeof body.command_id === 'string' ? lastAck(body.command_id) : undefined;
    },
    drive(vehicle, leaseId, seq, throttle, sentMs) {
      client.send({ type: 'drive', vehicle_id: vehicle, lease_id: leaseId, seq, throttle, ...(sentMs === undefined ? {} : { sent_ms: sentMs }) });
    },
    latest(v) {
      const t = telemetry(v).at(-1);
      if (!t) throw new Error(`no telemetry for ${v}`);
      return t;
    },
    telemetry,
    messages,
    until(vehicle, pred, maxMs) {
      const start = clock.now();
      while (clock.now() - start <= maxMs) {
        const t = telemetry(vehicle).at(-1);
        if (t && pred(t)) return clock.now() - start;
        clock.advance(50);
      }
      return -1;
    },
  };
  return h;
}
// TESTING.md L0.C4: the fake is deterministic. The same seed and the same inputs give a
// byte-identical output stream; a 15-minute day takes well under a second on a ManualClock.
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { createHash } from 'node:crypto';
import { ManualClock } from '../src/clock.ts';
import { FakeGateway } from '../fake/gateway.ts';
import { DLH1 } from '../fake/dlh1.ts';

const T0 = 1_790_000_000_000;
const DAY_MS = 15 * 60_000;

// A scripted day: random blasts, and a fixed set of inputs at fixed times covering every kind of
// command, a lease with driving, an e-stop and malformed lines. Returns every line one client saw.
function runDay(seed: number): { lines: string[]; cpuMs: number } {
  const clock = new ManualClock(T0);
  const gw = new FakeGateway(clock, { seed, site: DLH1, blasts: 'random' });
  gw.start();
  const c = gw.connect();
  c.send({ type: 'auth', email: '<redacted-email>' });
  const cmd = (id: string, vehicle: string, action: string, extra: object = {}) =>
    c.send({ type: 'command', command_id: id, vehicle_id: vehicle, action, operator_id: 'det', ...extra });

  const started = process.cpuUsage();
  clock.advance(5_000);
  cmd('d1', 'HT-01', 'HOLD');
  cmd('d2', 'HT-02', 'EXIT_ZONE');
  cmd('d3', 'HT-03', 'RETURN_TO_BAY');
  clock.advance(10_000);
  cmd('d4', 'HT-01', 'RESUME');
  cmd('d1', 'HT-01', 'HOLD'); // resend: original result
  cmd('d1', 'HT-01', 'RESUME'); // reuse: COMMAND_ID_REUSED
  c.send('{"type":"command", broken');
  cmd('d5', 'HT-04', 'TAKE_CONTROL');
  const ack = c.messages().filter((m) => m.type === 'command_ack' && m.command_id === 'd5').at(-1);
  const lease = ack && ack.type === 'command_ack' ? ack.lease_id ?? '' : '';
  for (let i = 1; i <= 30; i++) {
    c.send({ type: 'drive', vehicle_id: 'HT-04', lease_id: lease, seq: i, throttle: 0.4, sent_ms: clock.now() });
    clock.advance(100);
  }
  cmd('d6', 'HT-04', 'RELEASE_CONTROL', { lease_id: lease });
  cmd('d7', 'HT-05', 'ESTOP');
  clock.advance(20_000);
  cmd('d8', 'HT-05', 'CLEAR_ESTOP');
  cmd('d9', 'HT-05', 'RESUME');
  gw.injectFault('HT-06', 'HYD_PRESSURE_LOW');
  clock.advance(DAY_MS - clock.now() + T0);
  const used = process.cpuUsage(started);
  gw.stop();
  return { lines: c.lines, cpuMs: (used.user + used.system) / 1000 };
}

const digest = (lines: string[]) => createHash('sha256').update(lines.join('\n')).digest('hex');

test('L0.C4 the same seed and inputs give a byte-identical stream', () => {
  const a = runDay(42);
  const b = runDay(42);
  assert.ok(a.lines.length > 50_000, `${a.lines.length} lines in a 15-minute day`);
  assert.equal(a.lines.length, b.lines.length);
  assert.equal(digest(a.lines), digest(b.lines));
  const types = new Set(a.lines.map((l) => (JSON.parse(l) as { type: string }).type));
  for (const t of ['hello', 'telemetry', 'heartbeat', 'zone_event', 'command_ack', 'lease_event']) {
    assert.ok(types.has(t), `the stream includes ${t}`);
  }
});

test('L0.C4 a different seed gives a different day', () => {
  assert.notEqual(digest(runDay(42).lines), digest(runDay(43).lines));
});

// CPU time, not wall time: the claim is that the fake never waits on the real clock, and wall time
// also counts whatever else the machine is doing (the probe test runs in parallel).
test('a 15-minute day takes well under a second of CPU', () => {
  runDay(1); // warm up the JIT
  const { cpuMs } = runDay(2);
  console.log(`15-minute day: ${cpuMs.toFixed(0)} ms of CPU`);
  assert.ok(cpuMs < 1_000, `took ${cpuMs.toFixed(0)} ms of CPU`);
});
